-- V4: matching, employer/candidate profile gaps and FSP ID link (additive only).

-- Employer company: line of business and contact data (spec 2.1 «Профиль компании», 2.2 rule 2).
ALTER TABLE employer_companies
 ADD COLUMN industry TEXT NOT NULL DEFAULT '',
 ADD COLUMN contact_email TEXT NOT NULL DEFAULT '',
 ADD COLUMN contact_phone TEXT NOT NULL DEFAULT '',
 ADD COLUMN contact_telegram TEXT NOT NULL DEFAULT '',
 ADD COLUMN contact_note TEXT NOT NULL DEFAULT '';

-- Employer need: required stack forms the selection together with specialization and grade.
ALTER TABLE employer_needs
 ADD COLUMN tech_stack JSONB NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(tech_stack) = 'array');

-- Invitation carries the contact method the candidate should use (defaults from company contacts).
ALTER TABLE invitations
 ADD COLUMN contact_method TEXT NOT NULL DEFAULT '';

-- Candidate privacy (what employers see) and FSP participant binding.
ALTER TABLE candidate_profiles
 ADD COLUMN privacy JSONB NOT NULL DEFAULT '{"fullName":true,"techStack":true,"experience":true,"cvHistory":true,"softSkills":true,"fspAchievements":true}'::jsonb,
 ADD COLUMN fsp_id TEXT,
 ADD COLUMN fsp_linked_at TIMESTAMPTZ;
CREATE UNIQUE INDEX candidate_profiles_fsp_id_key ON candidate_profiles(fsp_id) WHERE fsp_id IS NOT NULL;

-- Achievements: provenance and structured result data (imported FSP results are rows with source='fsp').
ALTER TABLE achievements
 ADD COLUMN source TEXT NOT NULL DEFAULT 'manual',
 ADD COLUMN external_id TEXT,
 ADD COLUMN event_name TEXT NOT NULL DEFAULT '',
 ADD COLUMN discipline TEXT NOT NULL DEFAULT '',
 ADD COLUMN event_date DATE,
 ADD COLUMN level TEXT NOT NULL DEFAULT '' CHECK (level IN ('','regional','federal','international')),
 ADD COLUMN place INTEGER CHECK (place IS NULL OR place > 0),
 ADD COLUMN result_role TEXT NOT NULL DEFAULT '' CHECK (result_role IN ('','winner','prize','finalist','participant'));
CREATE UNIQUE INDEX achievements_source_external_key ON achievements(candidate_id, source, external_id) WHERE external_id IS NOT NULL;

-- Mock FSP registry (SYNTHETIC demo data, *@demo.fsp.local, events marked «(демо)»).
-- Stand-in for the real FSP registry API behind the FspRegistry interface; never real people.
CREATE TABLE fsp_registry_participants (
 fsp_id TEXT PRIMARY KEY CHECK (fsp_id ~ '^FSP-[0-9]{6}$'),
 email TEXT NOT NULL UNIQUE,
 full_name TEXT NOT NULL,
 region TEXT NOT NULL DEFAULT ''
);
CREATE TABLE fsp_registry_results (
 id TEXT PRIMARY KEY,
 fsp_id TEXT NOT NULL REFERENCES fsp_registry_participants(fsp_id) ON DELETE CASCADE,
 event_name TEXT NOT NULL,
 discipline TEXT NOT NULL,
 event_date DATE NOT NULL,
 level TEXT NOT NULL CHECK (level IN ('regional','federal','international')),
 place INTEGER CHECK (place IS NULL OR place > 0),
 result TEXT NOT NULL CHECK (result IN ('winner','prize','finalist','participant')),
 team_name TEXT
);
CREATE INDEX fsp_registry_results_participant_idx ON fsp_registry_results(fsp_id, event_date DESC);
-- Seed generated deterministically (40 participants, 80 results; FSP-100001 = showcase record,
-- FSP-100002 = single regional participation, FSP-100003 = registered without results).
